"""Kazakh result sections generated exclusively from frozen JSON reports."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def read(name):
    return json.loads((ROOT / 'reports' / name).read_text(encoding='utf-8'))


def add_results(doc):
    temporal = read('temporal.json')
    transfer = read('transfer.json')
    lab = read('experiment-lab.json')
    fmt = lambda x: f'{x:.4f}'
    doc.h('4.7 BRFSS моделін 2024 жылғы деректерге қолдану', 2)
    doc.p('Бұл қосымша тәжірибеде 2023 жылғы дайын логистикалық регрессия өзгертілмей қолданылды. Модель, алдын ала өңдеу және шешім шегі қайта таңдалған жоқ. 2024 жылғы деректерде BPHIGH6 және TOLDHI3 бағандары болмағандықтан, гипертензия мен холестерин белгілері бос мән ретінде берілді. Сондықтан жылдар арасындағы айырмашылықты тек уақыт әсерімен түсіндіруге болмайды [9].')
    labels = ['2023 бастапқы тест', '2023 екі белгі жасырылған', '2024 жаңа респонденттер']
    doc.table(['Таңдама', 'n', 'ROC-AUC', 'AP', 'Recall', 'Brier'], [
        [label, f"{c['n']:,}".replace(',', ' '), *[fmt(c['metrics'][k]) for k in ('roc_auc', 'average_precision', 'recall', 'brier')]]
        for label, c in zip(labels, temporal['cohorts'])
    ], [155, 65, 70, 65, 70, 70])
    a, masked, b = temporal['cohorts']
    doc.p(f"Бірдей {a['n']:,} тест жолында екі белгіні жасыру сезімталдықты {a['metrics']['recall']:.1%}-дан {masked['metrics']['recall']:.1%}-ға төмендетті. 2024 жылғы таңдамадағы сезімталдық {b['metrics']['recall']:.1%} болды. Бұл бақылау белгілердің қолжетімділігі өзгергенде бекітілген шектің мінез-құлқы өзгеретінін көрсетеді. Нәтиже шекті тест бойынша қайта таңдауға негіз болған жоқ.")
    doc.p(f"Барлық жол үшін шек {temporal['threshold']:.6f}. Кестедегі нәтижелер салмақталмаған. 2023 және 2024 жылдарда әртүрлі респонденттер сұралған: бұл бойлық бақылау да, бір адамның келесі жылғы ауруын болжау да емес. Интервалдар толық күрделі сауалнама жоспарын есепке алмайды. Дерек: reports/temporal.json; бақылау сомалары мен өңдеу деректері сол есепте сақталған.")
    doc.h('4.8 UCI моделінің орталықтар арасындағы тасымалы', 2)
    doc.p('Cleveland дерегінде оқытылған Random Forest Hungary, Switzerland және VA тарихи таңдамаларына қайта оқытусыз қолданылды. Әр орталық бөлек көрсетілді; біріктірілген үздік көрсеткіш есептелмеді. Барлық жазба, соның ішінде интерфейс шектерінен тыс бастапқы мәндер сақталды. Өңдеу параметрлері Cleveland оқытуынан алынды. Бұл ретроспективті тасымал аудиті; клиникалық жарамдылықтың дәлелі емес [2].')
    doc.table(['Орталық', 'n', 'Оң класс', 'ROC-AUC', 'AP', 'Recall'], [
        [c['center'], c['n'], f"{c['prevalence']:.1%}", *[fmt(c['metrics'][k]) for k in ('roc_auc', 'average_precision', 'recall')]]
        for c in transfer['cohorts']
    ], [115, 55, 85, 85, 80, 75])
    doc.p('Орталықтардағы ауру жиілігі мен жетіспейтін белгілер үлесі әртүрлі. Мысалы, Switzerland таңдамадағы жоғары AP ауруы бар жазбалардың үлкен үлесімен бірге түсіндірілуі керек; ол өздігінен жақсы калибрлеуді немесе барлық ортаға жарамдылықты білдірмейді. Осы тасымал есебінде сенімділік интервалдары есептелмеген. Жазба сәйкестігі тексерілгенімен, пациент идентификаторларының шектеулігі толық тәуелсіздікті кепілдемейді. Дерек: reports/transfer.json.')
    doc.h('4.9 Оқыту көлемі мен бұзылған кіріске сезімталдық', 2)
    doc.p('3.0 нұсқасының тәжірибе бөлімінде төрт сақталған іске қосу бар: екі дерек жиыны және екі алгоритм. BRFSS үшін бастапқы оқыту жиынынан алынған 6 000 жол, UCI үшін 303 Cleveland жазбасы қолданылды. Үш стратификацияланған бөлу, бірдей seed және 0,5 шегі пайдаланылды. Екі алгоритмде де класс салмағы balanced. Бұл тәжірибелер бастапқы жеті модельді салыстырудан бөлек; олар негізгі модельді ауыстырмайды.')
    doc.table(['Дерек және алгоритм', 'n', 'ROC-AUC', 'AP', 'AP SD'], [
        [r['config']['dataset'].upper() + ' / ' + ('Logistic Regression' if r['config']['algorithm'] == 'logistic_regression' else 'Random Forest'), r['n'], fmt(r['baseline']['roc_auc']['mean']), fmt(r['baseline']['average_precision']['mean']), fmt(r['baseline']['average_precision']['sd'])]
        for r in lab['runs']
    ], [220, 55, 80, 70, 70])
    doc.p('Оқыту қисығы әр сыртқы оқыту бөлігінің 20, 40, 60, 80 және 100 пайызында есептелді. Толтыру, кодтау және масштабтау әр ішкі таңдамада қайта үйренді. Тұрақты тексеру бөлігі өңдеуді үйретуге қатыспады. Қосымша сынақтарда мәндерді кездейсоқ босату, сандық белгілерге оқыту стандартты ауытқуына қатысты шу қосу және жеке белгіні жасыру қарастырылды. Бұлар табиғи ауру механизмін емес, берілген модельдің кіріс өзгерісіне сезімталдығын зерттейді.')
    doc.p('AP SD үш бөліктегі стандартты ауытқуды білдіреді, 95 пайыздық сенімділік интервалы емес. Бір жазбаға қолданылған бірнеше бұрмалау жаңа тәуелсіз пациенттер санын арттырмайды. Жаңа шағын тәжірибелер мен негізгі толық оқыту нәтижелері бірдей бюджеттегі жарыс ретінде салыстырылмайды. Толық қисықтар, сынақтар мен конфигурациялар reports/experiment-lab.json файлында және интерфейсте берілген.')


def verification_text():
    r = read('release_3_0_validation.json')
    evidence = 'reports/verification_3_0_python.xml және reports/verification_3_0_worker.txt'
    if (ROOT/'reports/research_extension_validation.json').exists():
        latest = read('research_extension_validation.json')
        r = {**r, 'python': {'passed': latest['python_passed']}, 'worker': {'passed': latest['worker_passed']}}
        evidence = 'reports/research_extension_tests.xml және reports/research_extension_worker.txt'
    return (f"{r['checked_date']} күнгі қайта тексеруде Python жиынындағы {r['python']['passed']} тест және Worker жиынындағы {r['worker']['passed']} тест өтті; қате саны нөл. "
            'Python 3.12 ортасында бекітілген тәуелділіктер қолданылды. ASGI қосылу мекенжайын тестке беру тәсілі орнатылған Starlette нұсқасына сәйкестендірілді; loopback және Origin қорғаныстары өзгертілген жоқ. '
            'TypeScript, Vite және Worker жинақталуы тексерілді. Docker үшін Python нұсқасы мен тәуелділіктер тізімі сәйкестендірілді, бірақ Docker Engine іске қосылмағандықтан контейнерлік іске қосу тексерілген жоқ. '
            f'Бұл техникалық тексерулер пайдаланушылармен зерттеуді немесе клиникалық валидацияны алмастырмайды. Нақты хаттамалар {evidence} файлдарында сақталған.')


def add_defense_update(doc):
    doc.h('3.0 нұсқасының нәтижелерін қорғауда түсіндіру', 2)
    t = read('temporal.json')['cohorts']
    doc.p(f"Негізгі модельді таңдағаннан кейін оны жаңа жылға қайта оқытусыз қолдандым. 2023 тестіндегі сезімталдық {t[0]['metrics']['recall']:.1%}, екі белгіні жасырғандағы сезімталдық {t[1]['metrics']['recall']:.1%}, ал 2024 таңдамада {t[2]['metrics']['recall']:.1%} болды. Сондықтан барлық айырманы уақытпен байланыстырмаймын: 2024 жылы екі белгі қолжетімсіз. Бұл болашақ аурудың болжамы емес, басқа респонденттердегі тіркелген жағдайды жіктеу.")
    doc.p('Қосымшада оқыту қисықтары мен кіріс бұрмалануының әсері көрсетіледі. Төрт қосымша тәжірибе негізгі модельді ауыстырмайды. Үш орталықтағы UCI тасымалы бөлек тарихи аудит ретінде берілген. Артерияның үшөлшемді көрінісі оқу иллюстрациясы ғана: ол адамның нақты тамырын қалпына келтірмейді және модель бағасынан стеноз есептемейді.')
    doc.p(verification_text())
